  'anaesthetic': { definition: 'A substance that causes loss of sensation, used during medical procedures.', example: 'The dentist applied a local anaesthetic before beginning the procedure.' },
  'anarchical': { definition: 'Without order, law, or authority; in a state of complete disorder.', example: 'The meeting descended into an anarchical shouting match within minutes.' },
  'antagonise': { definition: 'To cause hostility or opposition in someone; to provoke or irritate.', example: 'His comments were designed to antagonise rather than resolve the dispute.' },
