  'aptitude': { definition: 'A natural ability or talent for something; a readiness to learn.', example: 'She showed a strong aptitude for mathematics from an early age.' },
  'archaeology': { definition: 'The study of human history through the excavation of sites and artefacts.', example: 'Archaeology has uncovered thousands of years of Indigenous Australian history.' },
  'aristocrat': { definition: 'A member of the highest social class, typically with inherited wealth and titles.', example: 'The aristocrat lived in an enormous estate outside the city.' },
  'arithmetic': { definition: 'The branch of mathematics dealing with numbers and basic operations.', example: 'Strong arithmetic skills are important for everyday financial decisions.' },
  'articulate': { definition: 'Able to express ideas clearly and fluently; to put into words.', example: 'She was highly articulate and spoke confidently in front of the crowd.' },
  'assessment': { definition: 'The process of evaluating or judging the quality or ability of something.', example: 'The teacher used a range of methods to ensure fair assessment.' },
  'assimilate': { definition: 'To absorb and integrate into a wider culture or system.', example: 'New students often find it takes time to assimilate into school life.' },
