  'bureaucracy': { definition: 'A system of government with complex rules and many departments.', example: 'Cutting through the bureaucracy took far longer than expected.' },
  'cacophony': { definition: 'A harsh, discordant mixture of sounds; a jarring noise.', example: 'The cacophony of the construction site made it impossible to concentrate.' },
