  'camouflage': { definition: 'Colouring or covering that conceals something by blending it into surroundings.', example: 'The stick insect\'s camouflage made it nearly invisible on the bark.' },
  'catastrophe': { definition: 'An event causing great harm and distress; a disaster of significant magnitude.', example: 'The bushfire was a catastrophe that destroyed entire communities.' },
